var SEQ=1;
function add(list, s){ if(!s||!s.code) return list; return list.concat([{id:SEQ++, title:(s.title||'snippet').trim(), code:s.code, lang:(s.lang||'text').trim()}]); }
function remove(list, id){ return list.filter(function(x){ return x.id!==id; }); }
function search(list, q){ q=(q||'').trim().toLowerCase(); if(!q) return list; return list.filter(function(x){ return (x.title+x.code+x.lang).toLowerCase().indexOf(q)>=0; }); }
function byLang(list, lang){ lang=(lang||'').trim().toLowerCase(); if(!lang) return list; return list.filter(function(x){ return x.lang.toLowerCase()===lang; }); }
var EXPORTS={add:add,remove:remove,search:search,byLang:byLang};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SnippetForgePure = EXPORTS; }
